        $Exception
    )

    switch (Get-WriteFailureKind -Exception $Exception) {
        'denied' {
            return "Access denied writing to $Directory. Run PowerShell as Administrator, or pass -InstallDir with a directory you can write to. ($($Exception.Message))"
