#!/usr/bin/env python3
"""Run one isolated, ephemeral Codex CLI goal with explicit parameters."""

from __future__ import annotations

import argparse
import os
import shutil
import subprocess
import sys
from pathlib import Path


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--goal", required=True, help="Goal and observable success criteria")
    parser.add_argument(
        "--role",
        choices=("pm", "dev", "qa-fast", "qa-critical"),
        help="Role preset that selects a model and operation",
    )
    parser.add_argument("--model", help="Codex model slug; overrides the profile default")
    parser.add_argument("--cwd", required=True, help="Child agent workspace")
    parser.add_argument(
        "--sandbox",
        choices=("read-only", "workspace-write", "danger-full-access"),
        default="workspace-write",
    )
    parser.add_argument("--timeout", type=int, default=900, help="Timeout in seconds")
    parser.add_argument("--output", help="File for the child agent's final message")
    parser.add_argument("--profile", help="Optional Codex config profile")
    parser.add_argument("--kdd-root", help="KDD repository root for context inputs")
    parser.add_argument(
        "--kdd-prefix",
        action="append",
        default=[],
        help="KDD-relative static file to prepend; repeat in exact desired order",
    )
    parser.add_argument(
        "--kdd-contract",
        help="KDD context contract JSON; runs scripts/assemble_context.py",
    )
    parser.add_argument("--config", action="append", default=[], help="Repeated key=value override")
    parser.add_argument("--image", action="append", default=[], help="Repeated image path")
    parser.add_argument("--skip-git-repo-check", action="store_true")
    parser.add_argument("--no-ephemeral", action="store_true", help="Allow session persistence")
    parser.add_argument(
        "--unsafe",
        action="store_true",
        help="Bypass approvals and sandboxing; use only with explicit authorization",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    codex = shutil.which("codex")
    if not codex:
        print("codex was not found on PATH", file=sys.stderr)
        return 127

    cwd = Path(args.cwd).expanduser().resolve()
    if not cwd.is_dir():
        print(f"Child workspace does not exist: {cwd}", file=sys.stderr)
        return 2

    prompt = build_prompt(args, cwd)

    profile_models = {
        "pm": "gpt-5.6-terra",
        "dev": "gpt-5.6-sol",
        "qa-fast": "gpt-5.6-luna",
        "qa-critical": "gpt-5.6-terra",
    }
    model = args.model or profile_models.get(args.role, "gpt-5.6-luna")
    is_critical_qa = args.role == "qa-critical"
    command = [codex, "exec"]
    command.extend(["--model", model, "--json"])
    command.extend(["--cd", str(cwd)])
    if not args.no_ephemeral:
        command.append("--ephemeral")
    if args.unsafe:
        command.append("--dangerously-bypass-approvals-and-sandbox")
    else:
        command.extend(["--sandbox", args.sandbox])
    if args.profile:
        command.extend(["--profile", args.profile])
    if args.skip_git_repo_check:
        command.append("--skip-git-repo-check")
    for override in args.config:
        command.extend(["--config", override])
    for image in args.image:
        command.extend(["--image", image])
    if args.output:
        command.extend(["--output-last-message", str(Path(args.output).expanduser().resolve())])

    try:
        completed = subprocess.run(command + [prompt], cwd=cwd, timeout=args.timeout)
    except subprocess.TimeoutExpired:
        print(f"Codex child timed out after {args.timeout}s", file=sys.stderr)
        return 124
    except OSError as exc:
        print(f"Failed to launch Codex: {exc}", file=sys.stderr)
        return 126
    return completed.returncode


def build_prompt(args: argparse.Namespace, cwd: Path) -> str:
    """Build a stable KDD prefix followed by the variable goal."""
    root = Path(args.kdd_root).expanduser().resolve() if args.kdd_root else cwd
    sections = []

    for relative in args.kdd_prefix:
        path = (root / relative).resolve()
        if not path.is_file():
            raise SystemExit(f"KDD prefix file does not exist: {path}")
        content = path.read_text(encoding="utf-8").replace("\r\n", "\n").rstrip()
        label = path.relative_to(root).as_posix()
        sections.append(f"--- KDD_STATIC_FILE: {label} ---\n{content}")

    if args.kdd_contract:
        contract = (root / args.kdd_contract).resolve()
        assembler = root / "scripts" / "assemble_context.py"
        if not contract.is_file():
            raise SystemExit(f"KDD contract does not exist: {contract}")
        if not assembler.is_file():
            raise SystemExit(f"KDD assembler does not exist: {assembler}")
        result = subprocess.run(
            [sys.executable, str(assembler), str(contract), args.goal, "-v"],
            cwd=root,
            capture_output=True,
            text=True,
            encoding="utf-8",
            env={**os.environ, "PYTHONIOENCODING": "utf-8"},
            check=False,
        )
        if result.returncode != 0:
            detail = result.stderr.strip() or result.stdout.strip()
            raise SystemExit(f"KDD context assembly failed ({result.returncode}): {detail}")
        start = result.stdout.find("--- context ---")
        end = result.stdout.find("--- /context ---", start + 1)
        if start < 0 or end < 0:
            raise SystemExit("KDD assembler output did not contain context markers")
        sections.append(result.stdout[start + len("--- context ---"):end].strip())

    if not sections:
        return args.goal
    static_prefix = "\n\n".join(sections)
    return (
        "KDD_CONTEXT_V1\n"
        + static_prefix
        + "\n\n--- DYNAMIC_GOAL ---\n"
        + args.goal
    )


if __name__ == "__main__":
    raise SystemExit(main())
#!/usr/bin/env python3
"""Report optional evidence as PASS, FAIL or SKIP in GitHub Actions."""

import argparse
import json
import os
from pathlib import Path
import sys


LAYERS = {
    'security': ('KDD_SECURITY_SCAN_DIR', 'findings.json'),
    'compliance': ('KDD_COMPLIANCE_SCAN_DIR', 'findings.json'),
    'privacy': ('KDD_PRIVACY_SCAN_DIR', 'findings.json'),
    'accessibility': ('KDD_ACCESSIBILITY_SCAN_DIR', 'findings.json'),
    'dependency-eol': ('KDD_DEPENDENCY_EOL_SCAN_DIR', 'findings.json'),
    'observability': ('KDD_OBSERVABILITY_SCAN_DIR', 'findings.json'),
    'test-coverage': ('KDD_TEST_COVERAGE_SCAN_DIR', 'findings.json'),
    'quality': ('KDD_QUALITY_POLICY', ''),
}


def _names(value):
    names = [part.strip() for part in value.split(',') if part.strip()]
    if len(names) != len(set(names)):
        raise ValueError('duplicate evidence layer')
    unknown = set(names) - set(LAYERS)
    if unknown:
        raise ValueError('unknown evidence layer: ' + ', '.join(sorted(unknown)))
    return names


def _source(layer, environ):
    variable, filename = LAYERS[layer]
    configured = environ.get(variable, '')
    path = Path(configured) if configured else None
    return path / filename if path is not None and filename else path


def _outcome(layer, environ):
    key = 'KDD_{}_OUTCOME'.format(layer.upper().replace('-', '_'))
    return environ.get(key, '').lower()


def _status(layer, required, evidence):
    exists, outcome, summary = evidence
    if summary and outcome == 'failure':
        return 'FAIL', 'validator outcome: failure'
    if not exists:
        if layer in required:
            return 'FAIL', 'required evidence missing'
        return 'SKIP', 'evidence absent'
    if not summary:
        return 'PRESENT', 'validator has not run yet'
    if outcome == 'success':
        return 'PASS', 'evidence validated by CI step'
    return 'FAIL', 'validator outcome: ' + (outcome or 'not run')


def evaluate_layers(layers, required, environ, summary=False):
    if set(layers) - set(LAYERS) or set(required) - set(layers):
        raise ValueError('unknown or out-of-scope evidence layer')
    rows = []
    for layer in layers:
        source = _source(layer, environ)
        exists = source is not None and source.is_file()
        outcome = _outcome(layer, environ) if summary else ''
        status, reason = _status(layer, required, (exists, outcome, summary))
        if exists and layer != 'quality':
            try:
                data = json.loads(source.read_text(encoding='utf-8-sig'))
                if not isinstance(data, dict):
                    raise ValueError('expected a JSON object')
                identifier = data.get('scanId', '')
                if isinstance(identifier, str) and identifier.startswith('example_') and status != 'FAIL':
                    status = 'FAIL' if layer in required else 'SKIP'
                    reason = 'example scan is not project evidence'
            except (ValueError, OSError, UnicodeError):
                status, reason = 'FAIL', 'invalid evidence JSON'
        rows.append({'layer': layer, 'status': status, 'source': str(source or ''),
                     'reason': reason})
    return rows


def _markdown(rows):
    lines = ['## Optional KDD evidence', '', '| Layer | Status | Source | Reason |',
             '|---|---|---|---|']
    for row in rows:
        cells = [str(row[key]).replace('|', '\\|').replace('\n', ' ')
                 for key in ('layer', 'status', 'source', 'reason')]
        lines.append('| ' + ' | '.join(cells) + ' |')
    return '\n'.join(lines) + '\n'


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('mode', choices=('check', 'summary'))
    parser.add_argument('--layers', required=True, help='comma-separated layer names')
    args = parser.parse_args(argv)
    try:
        layers = _names(args.layers)
        required = set(_names(os.environ.get('KDD_REQUIRED_EVIDENCE', '')))
        rows = evaluate_layers(layers, required, os.environ, args.mode == 'summary')
    except ValueError as exc:
        parser.error(str(exc))
    for row in rows:
        print('{status} [{layer}] {source}: {reason}'.format(**row))
    if args.mode == 'summary':
        counts = {state: sum(row['status'] == state for row in rows)
                  for state in ('PASS', 'FAIL', 'SKIP')}
        print('Summary: PASS={PASS} FAIL={FAIL} SKIP={SKIP}'.format(**counts))
        summary_path = os.environ.get('GITHUB_STEP_SUMMARY')
        if summary_path:
            with open(summary_path, 'a', encoding='utf-8') as target:
                target.write(_markdown(rows))
    return int(any(row['status'] == 'FAIL' for row in rows))


if __name__ == '__main__':
    sys.exit(main())
#!/usr/bin/env python3
"""Gate de perimetro (Contrato 28).

Validador determinista: dado un task contract (clave `touch_only`) y la lista
de archivos cambiados, falla si algo cayo fuera del perimetro. Parser mini-YAML
copiado identico de validate_contracts.py para garantizar coherencia.

Sin red, sin subprocess. Solo stdlib.
"""

import fnmatch
import sys


# ---------------------------------------------------------------------------
# Parser YAML minimal (identico a validate_contracts.py)
# ---------------------------------------------------------------------------

def _split_inline_list(inner):
    """Parte el contenido entre [ ] respetando comillas simples/dobles."""
    items = []
    buf = []
    quote = None
    for ch in inner:
        if quote:
            buf.append(ch)
            if ch == quote:
                quote = None
        elif ch in ("'", '"'):
            quote = ch
            buf.append(ch)
        elif ch == ',':
            items.append(''.join(buf).strip())
            buf = []
        else:
            buf.append(ch)
    last = ''.join(buf).strip()
    if last:
        items.append(last)
    return items


def _parse_scalar(value):
    value = value.strip()
    if value.startswith('[') and value.endswith(']'):
        inner = value[1:-1].strip()
        if not inner:
            return []
        return [_parse_scalar(item) for item in _split_inline_list(inner)]
    if len(value) >= 2 and value[0] in ("'", '"') and value[-1] == value[0]:
        inner = value[1:-1]
        return inner.replace("''", "'") if value[0] == "'" else inner.replace('\\"', '"')
    return value


def _parse_block(lines, start, indent):
    """Parsea un bloque dict a partir de la linea `start` con indent `indent`.

    Devuelve (dict, indice_siguiente).
    """
    result = {}
    i = start
    n = len(lines)
    while i < n:
        line = lines[i]
        if not line.strip():
            i += 1
            continue
        cur_indent = len(line) - len(line.lstrip(' '))
        if cur_indent < indent:
            break
        if cur_indent > indent:
            i += 1
            continue
        stripped = line.strip()
        if ':' not in stripped:
            i += 1
            continue
        key, _, value = stripped.partition(':')
        key = key.strip()
        value = value.strip()
        if value == '':
            j = i + 1
            child_indent = None
            while j < n:
                l = lines[j]
                if not l.strip():
                    j += 1
                    continue
                ci = len(l) - len(l.lstrip(' '))
                if ci <= indent:
                    break
                child_indent = ci
                break
            if child_indent is not None:
                child, j = _parse_block(lines, i + 1, child_indent)
                result[key] = child
                i = j
            else:
                result[key] = ''
                i += 1
        else:
            result[key] = _parse_scalar(value)
            i += 1
    return result, i


def parse_frontmatter(text):
    """Devuelve (dict, body_str) o (None, body) si no hay frontmatter valido."""
    lines = text.splitlines()
    if not lines or lines[0].strip() != '---':
        idx = 0
        while idx < len(lines) and not lines[idx].strip():
            idx += 1
        if idx >= len(lines) or lines[idx].strip() != '---':
            return None, text
        start = idx
    else:
        start = 0
    end = None
    for k in range(start + 1, len(lines)):
        if lines[k].strip() == '---':
            end = k
            break
    if end is None:
        return None, text
    fm_lines = lines[start + 1:end]
    body_lines = lines[end + 1:]
    data, _ = _parse_block(fm_lines, 0, 0)
    return data, '\n'.join(body_lines)


# ---------------------------------------------------------------------------
# Validacion del perimetro
# ---------------------------------------------------------------------------

def _normalize_path(p):
    """Normaliza ruta: backslashes a '/', quita './' al inicio, limpia lineas."""
    p = p.strip()
    if not p:
        return None
    p = p.replace('\\', '/')
    if p.startswith('./'):
        p = p[2:]
    return p if p else None


def _normalize_changed_files(changed_files):
    """Normaliza lista de cambiados: elimina vacios, duplicados, ordena."""
    normalized = []
    for cf in changed_files:
        norm = _normalize_path(cf)
        if norm:
            normalized.append(norm)
    return sorted(list(set(normalized)))


def _is_valid_touch_only(touch_only):
    """Verifica si touch_only es lista no vacia de strings no vacios."""
    if not isinstance(touch_only, list):
        return False
    if len(touch_only) == 0:
        return False
    for item in touch_only:
        if not isinstance(item, str) or len(item) == 0:
            return False
    return True


def _matches_any_pattern(path, patterns):
    """Devuelve True si path matchea alguno de los patrones (fnmatch posix)."""
    for pattern in patterns:
        if fnmatch.fnmatch(path, pattern):
            return True
    return False


def validate_perimeter(contract_path, changed_files):
    """Valida que los archivos cambiados estan dentro del perimetro touch_only.

    Args:
        contract_path: ruta al archivo .md del contrato
        changed_files: lista de rutas (normalizadas o no) que cambiaron

    Returns:
        lista de findings {'file','level','rule','msg'} ordenados por
        (file, rule, msg). 'file' es la ruta posix del contrato (relativa,
        tal como se la pasa).
    """
    findings = []
    file_rel = contract_path.replace('\\', '/')

    # Leer contrato
    try:
        with open(contract_path, 'r', encoding='utf-8') as fh:
            text = fh.read()
    except OSError:
        findings.append({
            'file': file_rel,
            'level': 'ERROR',
            'rule': 'FM_PARSE',
            'msg': 'contrato inexistente o no legible'
        })
        return findings

    # Parsear frontmatter
    data, _body = parse_frontmatter(text)
    if data is None:
        findings.append({
            'file': file_rel,
            'level': 'ERROR',
            'rule': 'FM_PARSE',
            'msg': "frontmatter YAML no encontrado o no delimitado por '---'"
        })
        return findings

    # Validar touch_only
    touch_only = data.get('touch_only')
    if not _is_valid_touch_only(touch_only):
        findings.append({
            'file': file_rel,
            'level': 'ERROR',
            'rule': 'TOUCH_ONLY_MISSING',
            'msg': 'touch_only ausente, no-lista, vacia o con items no-string/vacios'
        })
        return findings

    # Normalizar cambiados
    normalized = _normalize_changed_files(changed_files)
    if not normalized:
        return findings

    # Obtener tests y target del contrato (para checks especiales)
    tests_path = data.get('tests', '')
    target_path = data.get('target', '')

    # Validar cada archivo cambiado
    for changed in normalized:
        # Regla: TESTS_TOUCHED
        if changed == tests_path and tests_path != target_path:
            findings.append({
                'file': file_rel,
                'level': 'ERROR',
                'rule': 'TESTS_TOUCHED',
                'msg': 'el archivo {} (oraculo congelado) no debe cambiar (tests != target)'.format(changed)
            })
            continue  # No emitir OUT_OF_PERIMETER para este archivo

        # Regla: OUT_OF_PERIMETER
        if not _matches_any_pattern(changed, touch_only):
            findings.append({
                'file': file_rel,
                'level': 'ERROR',
                'rule': 'OUT_OF_PERIMETER',
                'msg': 'archivo {} fuera del perimetro touch_only'.format(changed)
            })

    # Ordenar por (file, rule, msg)
    findings.sort(key=lambda f: (f['file'], f['rule'], f['msg']))
    return findings


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def main(argv):
    """CLI: python scripts/validate_perimeter.py <contract.md> [--changed f1 f2 ...]

    Sin --changed, lee los paths de stdin (uno por linea).
    Imprime findings y resumen. Exit 0 sin ERRORs, 1 con >=1.
    """
    if len(argv) < 1:
        print("Uso: python scripts/validate_perimeter.py <contract.md> [--changed f1 f2 ...]")
        return 1

    contract_path = argv[0]
    changed_files = []

    # Parsear argumentos
    if len(argv) > 1 and argv[1] == '--changed':
        changed_files = argv[2:]
    else:
        # Leer de stdin
        try:
            for line in sys.stdin:
                changed_files.append(line.rstrip('\n\r'))
        except EOFError:
            pass

    # Validar
    findings = validate_perimeter(contract_path, changed_files)

    # Imprimir findings
    errors = [f for f in findings if f['level'] == 'ERROR']
    for f in findings:
        print("{} [{}] {}: {}".format(f['level'], f['rule'], f['file'], f['msg']))

    # Imprimir resumen
    normalized_changed = _normalize_changed_files(changed_files)
    n_changed = len(normalized_changed)
    n_errors = len(errors)
    print("Resumen: {} error(es), {} archivo(s) cambiados".format(n_errors, n_changed))

    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
"""Compare contract/oracle to an independently approved Git commit.

The caller must select the trusted reference, from outside implementer control.
This read-only check does not provide branch protection or a trusted runner.
"""
import argparse
from pathlib import Path
import subprocess
from validate_contracts import parse_frontmatter


def _git(root, *args):
    try:
        return subprocess.check_output(
            ['git', '-C', str(root), *args], stderr=subprocess.PIPE, timeout=30)
    except (subprocess.SubprocessError, OSError) as exc:
        raise ValueError('Cannot read approved Git reference or artifact') from exc


def _normalize(content):
    return content.replace(b'\r\n', b'\n').replace(b'\r', b'\n')


def _relative(root, file):
    try:
        return (root / file).resolve().relative_to(root).as_posix()
    except (ValueError, TypeError) as exc:
        raise ValueError('Artifact path escapes repository') from exc


def validate_baseline(contract, approved_ref, repo_root='.'):
    root = Path(repo_root).resolve()
    rel = _relative(root, contract)
    commit = _git(root, 'rev-parse', '--verify', '--end-of-options',
                  approved_ref + '^{commit}').decode().strip()
    approved_contract = _git(root, 'show', commit + ':' + rel)
    metadata, _ = parse_frontmatter(approved_contract.decode('utf-8'))
    if not isinstance(metadata, dict) or not metadata.get('tests'):
        raise ValueError('Approved contract must declare tests')
    oracle = _relative(root, metadata['tests'])
    findings = []
    for file, expected in [(rel, approved_contract),
                           (oracle, _git(root, 'show', commit + ':' + oracle))]:
        try:
            current = (root / file).read_bytes()
        except OSError:
            findings.append(file + ': approved artifact missing')
            continue
        if _normalize(current) != _normalize(expected):
            findings.append(file + ': differs from approved reference ' + commit)
    return findings


def validate_all_baselines(approved_ref, repo_root='.', contracts_dir='knowledge/contracts'):
    """Check every current and approved contract, including additions/deletions."""
    root = Path(repo_root).resolve()
    directory = _relative(root, contracts_dir)
    commit = _git(root, 'rev-parse', '--verify', '--end-of-options',
                  approved_ref + '^{commit}').decode().strip()
    approved = set(_git(root, 'ls-tree', '-r', '--name-only', commit, '--',
                        directory).decode('utf-8').splitlines())
    approved = {p for p in approved if p.endswith('.md') and
                not Path(p).name.startswith('TEMPLATE-')}
    current_dir = root / directory
    if not current_dir.is_dir():
        raise ValueError('Contracts directory missing: ' + directory)
    current = {p.relative_to(root).as_posix() for p in current_dir.glob('*.md')
               if not p.name.startswith('TEMPLATE-')}
    if not approved and not current:
        raise ValueError('No contracts found in approved reference or current tree')
    findings = []
    for contract in sorted(approved | current):
        if contract not in approved:
            findings.append(contract + ': not in approved reference ' + commit)
        elif contract not in current:
            findings.append(contract + ': approved contract missing')
        else:
            findings.extend(validate_baseline(contract, commit, root))
    return findings


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('contract', nargs='?')
    parser.add_argument('--all', action='store_true', help='check all contracts')
    parser.add_argument('--contracts-dir', default='knowledge/contracts')
    parser.add_argument('--approved-ref', required=True)
    parser.add_argument('--repo-root', default='.')
    args = parser.parse_args()
    if args.all == bool(args.contract):
        parser.error('specify exactly one of CONTRACT or --all')
    try:
        if args.all:
            findings = validate_all_baselines(args.approved_ref, args.repo_root,
                                              args.contracts_dir)
        else:
            findings = validate_baseline(args.contract, args.approved_ref, args.repo_root)
    except (ValueError, UnicodeError) as exc:
        print('FAIL: ' + str(exc))
        return 2
    for finding in findings:
        print('FAIL: ' + finding)
    if not findings:
        print('PASS: contract and oracle match the approved reference')
    return 1 if findings else 0


if __name__ == '__main__':
    raise SystemExit(main())
# ---------------------------------------------------------------------------

_TRUNC_MARKER = " [...truncated]"
_SUMM_MARKER = " [...summarized]"


def _compact(content, cap, mode, chars_per_token=REDACTED
    """Recorta content a `cap` tokens dejando un marcador.

    IMPORTANTE: ambos modos (``truncate`` y ``summarize``) son corte por
    caracteres determinista (sin LLM, sin resumen semantico). Solo difieren el
    marcador que dejan al cortar (``[...truncated]`` vs ``[...summarized]``).
    El modo ``summarize`` se mantiene aceptado por compatibilidad con la
    plantilla publicada, pero no resume: corta exactamente igual que
    ``truncate``; el nombre es historico, no descriptivo.

    `cap` >= 1 garantizado por la caller. Reserva espacio para el marcador
    para no exceder el tope de tokens.
    """
    marker = _TRUNC_MARKER if mode == "truncate" else _SUMM_MARKER
    max_chars = cap * chars_per_token
    if len(content) <= max_chars:
        return content  # cabe sin recortar
    room = max_chars - len(marker)
    if room <= 0:
        # cap tan chico que solo entra el marcador (o ni eso)
        return marker[:max_chars]
    return content[:room] + marker


# ---------------------------------------------------------------------------
# Helpers: per-node cutting para okf_nodes
# ---------------------------------------------------------------------------

def _assemble_okf_nodes(base_dir, task, cap, comp, chars_per_token):
    """Ensambla okf_nodes con ranking y corte por nodo.

    El corte por nodo aplica SIEMPRE (tambien en el fallback sin matches):
    cuando todo cabe, el resultado es la misma concatenacion separada por
    linea en blanco que el comportamiento previo (byte-identico); cuando no
    cabe, el primero que no entra se compacta (marcador incluido) y el resto
    se omite.

    Retorna dict con:
      - raw: contenido concatenado incluido (ya <= cap)
      - selected: lista alfabetica de TODOS los ids recuperados por el
        retriever (compat con el reporte previo, redundante a proposito);
        cut/omitted_nodes declaran aparte que le paso a cada parte
      - cut: id compactado (o None)
      - omitted_nodes: lista de ids omitidos (o None)
    """
    scored_rels, ids = _retrieve_okf_nodes(base_dir, task)

    parts = []
    used = 0
    selected_ids = []
    cut_id = None
    omitted_ids = []

    for idx, (score, name, rel) in enumerate(scored_rels):
        try:
            node_content = _read_file(base_dir, rel)
        except OSError:
            continue

        node_id = os.path.splitext(os.path.basename(rel))[0]
        node_tokens = _tokens(node_content, chars_per_token)

        # Cuenta el separador "\n\n" si no es el primer nodo
        separator_tokens = 0 if not parts else _tokens("\n\n", chars_per_token)

        # ¿Entra entero con el separador?
        if used + separator_tokens + node_tokens <= cap:
            parts.append(node_content)
            used += separator_tokens + node_tokens
            selected_ids.append(node_id)
        else:
            # No entra entero. ¿Cabe compactado?
            remaining = cap - used - separator_tokens
            if remaining > 0 and comp != "none":
                # Se compacta este (cut) y el resto se omite
                compacted = _compact(node_content, remaining, comp,
                                     chars_per_token)
                parts.append(compacted)
                used += separator_tokens + _tokens(compacted, chars_per_token)
                cut_id = node_id
                for _, _, rest_rel in scored_rels[idx + 1:]:
                    omitted_ids.append(
                        os.path.splitext(os.path.basename(rest_rel))[0])
            else:
                # Sin compaction o sin presupuesto: este y el resto se omiten
                omitted_ids.append(node_id)
                for _, _, rest_rel in scored_rels[idx + 1:]:
                    omitted_ids.append(
                        os.path.splitext(os.path.basename(rest_rel))[0])
            break

    raw = "\n\n".join(parts) if parts else ""

    return {
        "raw": raw,
        "selected": sorted(ids),  # TODOS los recuperados, alfabetico (compat)
        "cut": cut_id,
        "omitted_nodes": omitted_ids if omitted_ids else None,
    }


# ---------------------------------------------------------------------------
# Providers / retriever
# ---------------------------------------------------------------------------

def _read_file(base_dir, rel_path):
    path = os.path.join(base_dir, rel_path)
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read()

