# Ejecutor de autoridad local

## Intent
Implementar el [modelo de autoridad](../data_models/local-authority.md) sin modificar
el runner, el planificador ni los oraculos existentes. El host es confiable y el agente
entrega solicitudes de datos; no se ejecuta codigo proporcionado por el agente.

## Interface
`AuthorityExecutor(root, policy)`; `execute(request: dict) -> dict`;
`delegate(child_policy)` devuelve un handle restringido o PermissionError;
`operations_used` informa contador global y `audit_log` devuelve copia de eventos.
CLI documentada en el modelo. No hay concesion de autoridad via request.

## Invariants
- Aplicar schema, catalogo, rutas, protecciones y cuotas del modelo enlazado.
- Rechazos por permisos no crean directorios ni escriben archivos.
- Crear solo con apertura exclusiva; existentes nunca se sobrescriben.
- Los comandos son internos de lectura, sin shell/subprocess ni red.
- Delegacion reduce permisos, mantiene protecciones y comparte cuotas de ancestros.
- Operaciones concurrentes del mismo ejecutor respetan cuota bajo lock.
- Limites no soportados se rechazan; no se afirma sandbox de sistema operativo.

## Examples
- Crear allowed/new.txt bajo autoridad y touch_only coincidentes: ok true.
- Crear private/new.txt fuera del permiso: ok false, sin efectos y con escalation.
- Hijo solicita write ** con padre limitado: PermissionError, sin handle concedido.

## Do / Don't
- DO: proteger oraculos explicitamente y probar efectos reales con fixtures temporales.
- DON'T: permitir shell arbitraria, scripts del proyecto o usar politicas como texto orientativo.

## Tests
Oraculo tests/test_authority_executor.py escrito antes del codigo y sellado.
Pruebas de enlaces pueden SKIP solo si el sistema impide crear el fixture; reportarlo.

## Constraints
PARAR y reportar si requiere permisos del sistema adicionales, aislamiento de procesos
hostiles o modificar tests congelados. Nivel 2 no medido; budget declarativo.

"""Closed policy schema; no best-effort interpretation of unsupported powers."""
from dataclasses import dataclass
import os


COMMANDS = ('sha256', 'validate_json')
DEVICES = {'CON', 'PRN', 'AUX', 'NUL'} | {f'{p}{i}' for p in ('COM', 'LPT') for i in range(1, 10)}


def valid_path(value):
    if not isinstance(value, str) or not value:
        return False
    if any(ord(c) < 32 or c in '\\:*?"<>|' for c in value):
        return False
    for segment in value.split('/'):
        if not segment or segment in ('.', '..') or segment.endswith(('.', ' ')):
            return False
        if segment.split('.')[0].upper() in DEVICES:
            return False
    return True


def _pattern(value):
    if value == '**':
        return True
    if not isinstance(value, str):
        return False
    prefix = value[:-3] if value.endswith('/**') else value
    return valid_path(prefix) and not any(c in prefix for c in '[]')


def _list(value, checker):
    return (isinstance(value, list) and all(checker(v) for v in value)
            and len(set(value)) == len(value))


def _positive(value):
    return type(value) is int and value > 0


def _fold(value):
    return value.casefold() if os.name == 'nt' else value


def covers(parent, child):
    """Exact paths / prefix/** / ** have a decidable subset relation."""
    parent, child = _fold(parent), _fold(child)
    if parent == '**' or parent == child:
        return True
    return parent.endswith('/**') and child.startswith(parent[:-2])


def matches(patterns, path):
    return any(covers(pattern, path) for pattern in patterns)


@dataclass(frozen=True)
class Policy:
    read: tuple
    write: tuple
    execute: tuple
    touch_only: tuple
    protected_paths: tuple
    max_operations: int
    max_bytes: int


def parse_policy(value):
    fields = {'version', 'authority', 'touch_only', 'protected_paths', 'limits'}
    if not isinstance(value, dict) or set(value) != fields:
        raise ValueError('Invalid policy fields')
    if type(value['version']) is not int or value['version'] != 1:
        raise ValueError('Unsupported policy version')
    authority, limits = value['authority'], value['limits']
    if not isinstance(authority, dict) or set(authority) != {'read', 'write', 'execute'}:
        raise ValueError('Unsupported authority')
    if not isinstance(limits, dict) or set(limits) != {'max_operations', 'max_bytes'}:
        raise ValueError('Unsupported limits')
    patterns = (authority['read'], authority['write'], value['touch_only'], value['protected_paths'])
    if not all(_list(p, _pattern) for p in patterns):
        raise ValueError('Unsupported path patterns')
    if not _list(authority['execute'], lambda c: isinstance(c, str) and c in COMMANDS):
        raise ValueError('Unsupported command')
    if not all(_positive(limits[k]) for k in limits):
        raise ValueError('Invalid limits')
    return Policy(tuple(authority['read']), tuple(authority['write']), tuple(authority['execute']),
                  tuple(value['touch_only']), tuple(value['protected_paths']),
                  limits['max_operations'], limits['max_bytes'])


def allows_child(parent, child):
    for name in ('read', 'write', 'touch_only'):
        if not all(matches(getattr(parent, name), p) for p in getattr(child, name)):
            return False
    return (set(child.execute).issubset(parent.execute)
            and child.max_operations <= parent.max_operations
            and child.max_bytes <= parent.max_bytes)

"""Trusted operation broker. This is not a sandbox for arbitrary code."""
import argparse
from dataclasses import dataclass, field
import hashlib
import json
import os
from pathlib import Path
import stat
import threading

from src.authority_policy import COMMANDS, allows_child, matches, parse_policy, valid_path


class _Denied(Exception):
    def __init__(self, code, reason):
        self.code, self.reason = code, reason


@dataclass
class _Scope:
    policy: object
    identifier: str
    used: int = 0


@dataclass
class _State:
    root: Path
    lock: object = field(default_factory=threading.RLock)
    audit: list = field(default_factory=list)
    next_scope: int = 0


def _reparse(info):
    return (stat.S_ISLNK(info.st_mode)
            or bool(getattr(info, 'st_file_attributes', 0) & getattr(stat, 'FILE_ATTRIBUTE_REPARSE_POINT', 0x400)))


def _request(request):
    if not isinstance(request, dict) or not isinstance(request.get('op'), str):
        raise _Denied('INVALID_REQUEST', None)
    fields = {'read_file': {'op', 'path'}, 'write_file': {'op', 'path', 'text'},
              'run_command': {'op', 'path', 'command'}}
    if request['op'] not in fields:
        raise _Denied('UNSUPPORTED_OPERATION', 'unsupported_operation')
    if set(request) != fields[request['op']]:
        raise _Denied('INVALID_REQUEST', None)
    if not valid_path(request['path']):
        raise _Denied('INVALID_PATH', 'authority_expansion')
    if request['op'] == 'write_file' and not isinstance(request['text'], str):
        raise _Denied('INVALID_REQUEST', None)
    if request['op'] == 'run_command' and request['command'] not in COMMANDS:
        raise _Denied('UNSUPPORTED_COMMAND', 'unsupported_operation')


def _permissions(policy, request):
    path, operation = request['path'], request['op']
    if operation == 'write_file':
        if matches(policy.protected_paths, path):
            raise _Denied('PROTECTED_PATH', 'oracle_change')
        if not matches(policy.write, path) or not matches(policy.touch_only, path):
            raise _Denied('AUTHORITY_DENIED', 'authority_expansion')
    else:
        if not matches(policy.read, path):
            raise _Denied('AUTHORITY_DENIED', 'authority_expansion')
        if operation == 'run_command' and request['command'] not in policy.execute:
            raise _Denied('AUTHORITY_DENIED', 'authority_expansion')


def _safe_path(root, path):
    if root.resolve(strict=True) != root or _reparse(root.lstat()):
        raise _Denied('UNSAFE_PATH', 'authority_expansion')
    current = root
    for segment in path.split('/'):
        current = current / segment
        try:
            info = current.lstat()
        except FileNotFoundError:
            continue
        if _reparse(info):
            raise _Denied('UNSAFE_PATH', 'authority_expansion')
        if not (stat.S_ISREG(info.st_mode) or stat.S_ISDIR(info.st_mode)):
            raise _Denied('UNSAFE_PATH', 'authority_expansion')
        if stat.S_ISREG(info.st_mode) and info.st_nlink > 1:
            raise _Denied('UNSAFE_PATH', 'authority_expansion')
    if not current.resolve(strict=False).is_relative_to(root):
        raise _Denied('UNSAFE_PATH', 'authority_expansion')
    return current


def _read_bytes(path, limit):
    flags = os.O_RDONLY | getattr(os, 'O_NOFOLLOW', 0) | getattr(os, 'O_BINARY', 0)
    descriptor = os.open(path, flags)
    with os.fdopen(descriptor, 'rb') as stream:
        info = os.fstat(stream.fileno())
        if not stat.S_ISREG(info.st_mode) or info.st_nlink > 1:
            raise _Denied('UNSAFE_PATH', 'authority_expansion')
        if info.st_size > limit:
            raise _Denied('SIZE_LIMIT', 'budget_exhausted')
        content = stream.read(limit + 1)
    if len(content) > limit:
        raise _Denied('SIZE_LIMIT', 'budget_exhausted')
    return content


def _invalid_constant(value):
    raise ValueError('Non-JSON numeric constant')


def _run_command(command, content):
    if command == 'sha256':
        return hashlib.sha256(content).hexdigest()
    try:
        json.loads(content.decode('utf-8'), parse_constant=_invalid_constant)
    except (ValueError, UnicodeError, RecursionError):
        return {'valid': False}
    return {'valid': True}


def _perform(path, request, limit):
    if request['op'] == 'write_file':
        payload = request['text'].encode('utf-8')
        if len(payload) > limit:
            raise _Denied('SIZE_LIMIT', 'budget_exhausted')
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, 'O_NOFOLLOW', 0) | getattr(os, 'O_BINARY', 0)
        try:
            descriptor = os.open(path, flags, 0o600)
        except FileExistsError as exc:
            raise _Denied('OVERWRITE_NOT_SUPPORTED', 'destructive_action') from exc
        with os.fdopen(descriptor, 'wb') as stream:
            stream.write(payload)
        return {'bytes_written': len(payload)}
    content = _read_bytes(path, limit)
    if request['op'] == 'read_file':
        return content.decode('utf-8')
    return _run_command(request['command'], content)


class AuthorityExecutor:
    def __init__(self, root, policy):
        configured = parse_policy(policy)
        raw = Path(root).absolute()
        try:
            if _reparse(raw.lstat()) or not raw.is_dir():
                raise ValueError('Unsafe workspace root')
            resolved = raw.resolve(strict=True)
        except OSError as exc:
            raise ValueError('Workspace root unavailable') from exc
        self._state = _State(resolved)
        self._chain = (_Scope(configured, 'root'),)

    def delegate(self, child_policy):
        child = parse_policy(child_policy)
        if not allows_child(self._chain[-1].policy, child):
            raise PermissionError('Delegation would expand authority or limits')
        with self._state.lock:
            self._state.next_scope += 1
            handle = object.__new__(AuthorityExecutor)
            handle._state = self._state
            identifier = self._chain[-1].identifier + '/' + str(self._state.next_scope)
            handle._chain = self._chain + (_Scope(child, identifier),)
            return handle

    @property
    def operations_used(self):
        with self._state.lock:
            return self._chain[0].used

    @property
    def audit_log(self):
        with self._state.lock:
            return [dict(event) for event in self._state.audit]

    def _admit(self, request):
        _request(request)
        for scope in self._chain:
            _permissions(scope.policy, request)
        if any(s.used >= s.policy.max_operations for s in self._chain):
            raise _Denied('OPERATION_LIMIT', 'budget_exhausted')
        for scope in self._chain:
            scope.used += 1

    def _record(self, request, result):
        request = request if isinstance(request, dict) else {}
        operation = request.get('op')
        path = request.get('path')
        self._state.audit.append({'sequence': len(self._state.audit) + 1,
                                  'scope': self._chain[-1].identifier,
                                  'operation': operation[:64] if isinstance(operation, str) else None,
                                  'path': path[:512] if isinstance(path, str) else None,
                                  'ok': result['ok'], 'code': result['code']})
        return result

    def execute(self, request: dict) -> dict:
        """Authorize before effects; accepted attempts consume shared quotas."""
        with self._state.lock:
            try:
                self._admit(request)
                path = _safe_path(self._state.root, request['path'])
                limit = min(s.policy.max_bytes for s in self._chain)
                data = _perform(path, request, limit)
                result = {'ok': True, 'code': 'OK', 'data': data}
            except _Denied as denied:
                result = {'ok': False, 'code': denied.code}
                if denied.reason:
                    result['escalation'] = {'required': True, 'reason': denied.reason}
            except (OSError, UnicodeError, ValueError, RuntimeError):
                result = {'ok': False, 'code': 'IO_ERROR'}
            return self._record(request, result)


def _load(path):
    return json.loads(path.read_text(encoding='utf-8'))


def _outside_workspace(path, root):
    if path.resolve(strict=True).is_relative_to(root.resolve(strict=True)):
        raise ValueError('Control policy must live outside the workspace')
    return _load(path)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root', required=True, type=Path)
    parser.add_argument('--policy', required=True, type=Path)
    parser.add_argument('--requests', required=True, type=Path)
    parser.add_argument('--delegate', action='append', default=[], type=Path)
    args = parser.parse_args()
    try:
        executor = AuthorityExecutor(args.root, _outside_workspace(args.policy, args.root))
        for path in args.delegate:
            executor = executor.delegate(_outside_workspace(path, args.root))
        requests = _load(args.requests)
        if not isinstance(requests, list):
            raise ValueError('Requests must be a list')
        results = [executor.execute(request) for request in requests]
    except (OSError, ValueError, UnicodeError, RecursionError, RuntimeError):
        print(json.dumps({'ok': False, 'code': 'INVALID_CONFIGURATION'}))
        return 2
    print(json.dumps({'results': results, 'operations_used': executor.operations_used,
                      'audit': executor.audit_log}, sort_keys=True))
    return 0 if all(result['ok'] for result in results) else 1


if __name__ == '__main__':
    raise SystemExit(main())

"""Acceptance oracle: permission denial must precede filesystem effects."""
import copy
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest
from concurrent.futures import ThreadPoolExecutor

from src.authority_executor import AuthorityExecutor


def policy():
    return {'version': 1,
            'authority': {'read': ['allowed/**', 'tests/**'],
                          'write': ['allowed/**', 'tests/**'],
                          'execute': ['sha256', 'validate_json']},
            'touch_only': ['allowed/**', 'tests/**'],
            'protected_paths': ['tests/**'],
            'limits': {'max_operations': 10, 'max_bytes': 4096}}


def manifest(root):
    return {p.relative_to(root).as_posix(): hashlib.sha256(p.read_bytes()).hexdigest()
            for p in root.rglob('*') if p.is_file() and not p.is_symlink()}


class AuthorityTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.base = Path(self.temp.name)
        self.root = self.base / 'workspace'
        for name in ['allowed', 'private', 'tests']:
            (self.root / name).mkdir(parents=True)
        (self.root / 'allowed/data.json').write_text('{"value": 7}', encoding='utf-8')
        (self.root / 'private/secret.txt').write_text('do-not-disclose', encoding='utf-8')
        (self.root / 'tests/oracle.py').write_text('assert 1 == 1', encoding='utf-8')
        self.executor = AuthorityExecutor(self.root, policy())

    def test_create_then_read(self):
        result = self.executor.execute({'op': 'write_file', 'path': 'allowed/new.txt', 'text': 'hello'})
        self.assertTrue(result['ok'], result)
        self.assertEqual((self.root / 'allowed/new.txt').read_text(), 'hello')
        result = self.executor.execute({'op': 'read_file', 'path': 'allowed/new.txt'})
        self.assertEqual(result['data'], 'hello')

    def test_commands_are_internal_and_read_only(self):
        before = manifest(self.root)
        result = self.executor.execute({'op': 'run_command', 'path': 'allowed/data.json', 'command': 'sha256'})
        self.assertTrue(result['ok'], result)
        self.assertEqual(result['data'], hashlib.sha256((self.root / 'allowed/data.json').read_bytes()).hexdigest())
        result = self.executor.execute({'op': 'run_command', 'path': 'allowed/data.json', 'command': 'validate_json'})
        self.assertEqual(result['data'], {'valid': True})
        self.assertEqual(manifest(self.root), before)

    def test_invalid_json_is_not_executed(self):
        (self.root / 'allowed/code.txt').write_text('NaN', encoding='utf-8')
        result = self.executor.execute({'op': 'run_command', 'path': 'allowed/code.txt', 'command': 'validate_json'})
        self.assertTrue(result['ok'], result)
        self.assertEqual(result['data'], {'valid': False})

    def test_static_denials_have_no_effects(self):
        before = manifest(self.root)
        attempts = [
            {'op': 'write_file', 'path': 'private/new.txt', 'text': 'bad'},
            {'op': 'write_file', 'path': 'tests/oracle.py', 'text': 'assert True'},
            {'op': 'read_file', 'path': 'private/secret.txt'},
            {'op': 'run_command', 'path': 'allowed/data.json', 'command': 'shell'},
            {'op': 'run_command', 'path': 'private/secret.txt', 'command': 'sha256'},
        ]
        for request in attempts:
            with self.subTest(request=request):
                result = self.executor.execute(request)
                self.assertFalse(result['ok'])
                self.assertTrue(result['escalation']['required'])
                self.assertNotIn('do-not-disclose', json.dumps(result))
                self.assertEqual(manifest(self.root), before)
        self.assertEqual(self.executor.operations_used, 0)

    def test_execute_permission_not_implied_by_read(self):
        configured = policy()
        configured['authority']['execute'] = []
        result = AuthorityExecutor(self.root, configured).execute(
            {'op': 'run_command', 'path': 'allowed/data.json', 'command': 'sha256'})
        self.assertFalse(result['ok'])

    def test_touch_only_intersection(self):
        configured = policy()
