#!/usr/bin/env python3
"""Audit an implementation diff against an independently approved contract."""

import argparse
import ast
from pathlib import Path, PurePosixPath
import re
import subprocess
import sys
import tempfile

from validate_budgets import _budget_findings
from validate_contracts import parse_frontmatter
from validate_perimeter import validate_perimeter
from change_contract_multilang import audit_source


_SHA = re.compile(r'[0-9a-fA-F]{40}(?:[0-9a-fA-F]{24})?')


def _finding(rule, path, message):
    return {'rule': rule, 'path': path, 'msg': message}


def _safe_path(path):
    if not isinstance(path, str):
        return False
    value = PurePosixPath(path.replace('\\', '/'))
    return (bool(path) and not value.is_absolute()
            and '..' not in value.parts and value.as_posix() != '.')


def _git(root, *args):
    result = subprocess.run(['git', '-C', str(root), *args],
                            capture_output=True, timeout=30, check=False)
    if result.returncode:
        raise ValueError('Git command failed: ' + ' '.join(args))
    return result.stdout


def _blob(root, sha, path):
    result = subprocess.run(['git', '-C', str(root), 'show', sha + ':' + path],
                            capture_output=True, timeout=30, check=False)
    return result.stdout if result.returncode == 0 else None


def _changed_paths(root, base_ref, head_ref):
    _git(root, 'merge-base', '--is-ancestor', base_ref, head_ref)
    changed = _git(root, 'diff', '--name-only', '-z', base_ref, head_ref)
    return sorted(path.decode('utf-8') for path in changed.split(b'\0') if path)


def _perimeter_findings(contract_text, contract_path, changed):
    with tempfile.TemporaryDirectory(prefix='kdd-contract-') as temp:
        path = Path(temp) / 'contract.md'
        path.write_text(contract_text, encoding='utf-8')
        result = validate_perimeter(str(path), changed)
    return [_finding(item['rule'], contract_path, item['msg'])
            for item in result if item['level'] == 'ERROR']


def _imports(source, path):
    tree = ast.parse(source, filename=path)
    names = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            names.update(alias.name.split('.')[0] for alias in node.names)
        elif isinstance(node, ast.ImportFrom) and node.level == 0:
            names.add((node.module or '').split('.')[0])
    return names - {''}


def _is_local(root, head_ref, target, module):
    parent = PurePosixPath(target).parent
    prefixes = [module + '.py', module + '/']
    if parent != PurePosixPath('.'):
        prefixes.extend([str(parent / (module + '.py')),
                         str(parent / module) + '/'])
    tree = _git(root, 'ls-tree', '-r', '--name-only', head_ref, '--', *prefixes)
    return bool(tree.strip())


def _dependency_findings(root, head_ref, target, sources, allowed):
    try:
        before, after = sources
        new_imports = _imports(after, target) - _imports(before, target)
    except SyntaxError as exc:
        return [_finding('DEP_PARSE', target, str(exc))]
    permitted = {name.casefold() for name in allowed if isinstance(name, str)}
    findings = []
    for module in sorted(new_imports):
        if (module in sys.stdlib_module_names or module in sys.builtin_module_names
                or module.casefold() in permitted
                or _is_local(root, head_ref, target, module)):
            continue
        findings.append(_finding('DEP_UNDECLARED', target,
                                 'new external import not in deps_allowed: ' + module))
    return findings


def _manifest_candidates(target):
    suffix = PurePosixPath(target).suffix
    manifest_name = ('package.json' if suffix in ('.js', '.jsx', '.ts', '.tsx')
                     else 'go.mod' if suffix == '.go'
                     else 'Cargo.toml' if suffix == '.rs' else None)
    if manifest_name is None:
        return []
    parent = PurePosixPath(target).parent
    candidates = []
    while True:
        candidates.append(str(parent / manifest_name)
                          if parent != PurePosixPath('.') else manifest_name)
        if parent == PurePosixPath('.'):
            break
        parent = parent.parent
    return candidates


def _nearest_manifest(root, ref, candidates):
    return next((name for name in candidates
                 if _blob(root, ref, name) is not None), None)


def _multilang_findings(root, target, data, base_ref, head_ref):
    candidates = _manifest_candidates(target)
    if not candidates:
        return [_finding('CHECK_UNSUPPORTED', target,
                         'dependency and budget checks have no adapter')]
    before_manifest = _nearest_manifest(root, base_ref, candidates)
    after_manifest = _nearest_manifest(root, head_ref, candidates)
    if after_manifest is None:
        return [_finding('MANIFEST_PARSE', target,
                         'required dependency manifest is missing')]
    try:
        manifests = {
            'before': (_blob(root, base_ref, before_manifest) or b'').decode('utf-8')
            if before_manifest else '',
            'after': _blob(root, head_ref, after_manifest).decode('utf-8'),
        }
    except UnicodeError as exc:
        return [_finding('MANIFEST_PARSE', target, str(exc))]
    return audit_source(target, _blob(root, base_ref, target) or b'',
                        _blob(root, head_ref, target), data, manifests)


def _target_findings(root, data, base_ref, head_ref, changed):
    target = data.get('target')
    if not _safe_path(target):
        return [_finding('CONTRACT_TARGET', str(target), 'invalid target path')]
    target = target.replace('\\', '/')
    candidates = _manifest_candidates(target)
    before_manifest = _nearest_manifest(root, base_ref, candidates)
    after_manifest = _nearest_manifest(root, head_ref, candidates)
    manifest_changed = (before_manifest != after_manifest or
                        after_manifest in changed)
    if target not in changed and not manifest_changed:
        return []
    after_bytes = _blob(root, head_ref, target)
    if after_bytes is None:
        return [_finding('TARGET_MISSING', target, 'target missing at candidate SHA')]
    if not target.endswith('.py'):
        return _multilang_findings(root, target, data, base_ref, head_ref)
    try:
        after = after_bytes.decode('utf-8')
        before = (_blob(root, base_ref, target) or b'').decode('utf-8')
    except UnicodeError as exc:
        return [_finding('TARGET_ENCODING', target, str(exc))]
    findings = _dependency_findings(root, head_ref, target, (before, after),
                                    data.get('deps_allowed', []))
    with tempfile.TemporaryDirectory(prefix='kdd-target-') as temp:
        path = Path(temp) / 'candidate.py'
        path.write_text(after, encoding='utf-8')
        for item in _budget_findings(target, str(path), data.get('budget', {})):
            findings.append(_finding(item.rule, target, item.message))
    return findings


def audit_change(repo_root, contract_path, base_ref, head_ref):
    """Return deterministic findings for a Git diff under baseline policy."""
    if not _safe_path(contract_path):
        return [_finding('CONTRACT_PATH', str(contract_path),
                         'contract path must be repo-relative')]
    contract_path = contract_path.replace('\\', '/')
    if not (_SHA.fullmatch(base_ref) and _SHA.fullmatch(head_ref)):
        return [_finding('GIT_RANGE', contract_path, 'full commit SHAs required')]
    try:
        changed = _changed_paths(repo_root, base_ref, head_ref)
        contract_bytes = _blob(repo_root, base_ref, contract_path)
    except (OSError, ValueError, UnicodeError, subprocess.TimeoutExpired):
        return [_finding('GIT_RANGE', contract_path,
                         'baseline is unavailable or not an ancestor')]
    if contract_bytes is None:
        return [_finding('CONTRACT_BASE', contract_path,
                         'contract absent from approved baseline')]
    try:
        contract_text = contract_bytes.decode('utf-8')
        data, _body = parse_frontmatter(contract_text)
    except UnicodeError as exc:
        return [_finding('CONTRACT_BASE', contract_path, str(exc))]
    if not isinstance(data, dict):
        return [_finding('CONTRACT_BASE', contract_path,
                         'invalid approved contract')]
    try:
        findings = _perimeter_findings(contract_text, contract_path, changed)
        findings.extend(_target_findings(repo_root, data, base_ref,
                                         head_ref, changed))
    except (OSError, ValueError, subprocess.TimeoutExpired) as exc:
        return [_finding('AUDIT_ERROR', contract_path, str(exc))]
    return sorted(findings, key=lambda item: (item['path'], item['rule'],
                                              item['msg']))


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repo-root', default='.')
    parser.add_argument('--contract', required=True)
    parser.add_argument('--base-ref', required=True)
    parser.add_argument('--head-ref', required=True)
    args = parser.parse_args(argv)
    findings = audit_change(args.repo_root, args.contract, args.base_ref,
                            args.head_ref)
    for item in findings:
        print('ERROR [{}] {}: {}'.format(item['rule'], item['path'], item['msg']))
    print('Summary: FAIL={}'.format(len(findings)))
    return int(bool(findings))


if __name__ == '__main__':
    sys.exit(main())

"""Tree-sitter adapters for the opt-in Git change auditor."""

import json
import re
import tomllib

from tree_sitter import Language, Parser
import tree_sitter_go
import tree_sitter_javascript
import tree_sitter_rust
import tree_sitter_typescript


GRAMMARS = {
    '.js': tree_sitter_javascript.language,
    '.jsx': tree_sitter_javascript.language,
    '.ts': tree_sitter_typescript.language_typescript,
    '.tsx': tree_sitter_typescript.language_tsx,
    '.go': tree_sitter_go.language,
    '.rs': tree_sitter_rust.language,
}
JS = {'.js', '.jsx', '.ts', '.tsx'}
FUNCTIONS = {'function_declaration', 'function_expression',
             'generator_function_declaration', 'arrow_function',
             'method_definition', 'function_item', 'method_declaration'}
BRANCHES = {'if_statement', 'if_expression', 'for_statement', 'for_in_statement',
            'while_statement', 'do_statement', 'switch_case', 'case_clause',
            'catch_clause', 'ternary_expression', 'match_arm',
            'while_expression', 'for_expression', 'loop_expression',
            'expression_case', 'type_case', 'communication_case'}
NESTING_BRANCHES = (BRANCHES - {'expression_case', 'type_case',
                                'communication_case'}) | {
                                    'expression_switch_statement',
                                    'type_switch_statement', 'select_statement'}
RUST_LOCAL = {'std', 'core', 'alloc', 'crate', 'self', 'super'}


def _finding(rule, path, msg):
    return {'rule': rule, 'path': path, 'msg': msg}


def _walk(node):
    yield node
    for child in node.named_children:
        yield from _walk(child)


def _text(node, source):
    return source[node.start_byte:node.end_byte].decode('utf-8')


def _ext(target):
    return '.' + target.rsplit('.', 1)[-1] if '.' in target else ''


def _parse(target, source):
    tree = Parser(Language(GRAMMARS[_ext(target)]())).parse(source)
    if tree.root_node.has_error:
        raise ValueError('source contains syntax errors')
    return tree.root_node


def _json_manifest(source):
    data = json.loads(source)
    if not isinstance(data, dict):
        raise ValueError('package.json must be an object')
    deps = set()
    for field in ('dependencies', 'devDependencies', 'peerDependencies',
                  'optionalDependencies'):
        value = data.get(field, {})
        if not isinstance(value, dict):
            raise ValueError(field + ' must be an object')
        deps.update(value)
    return deps, None


def _cargo_manifest(source):
    data = tomllib.loads(source)
    targets = data.get('target', {})
    package = data.get('package', {})
    if not isinstance(targets, dict) or not isinstance(package, dict):
        raise ValueError('invalid Cargo target or package table')
    deps = set()
    for table in [data] + list(targets.values()):
        if not isinstance(table, dict):
            raise ValueError('invalid Cargo target table')
        for field in ('dependencies', 'dev-dependencies', 'build-dependencies'):
            entries = table.get(field, {})
            if not isinstance(entries, dict):
                raise ValueError('invalid Cargo dependency table')
            for name, value in entries.items():
                if isinstance(value, dict) and value.get('workspace'):
                    raise ValueError('Cargo workspace dependency requires unsupported resolution')
                deps.add(name)
    if data.get('patch') or data.get('replace'):
        raise ValueError('Cargo patch or replace requires unsupported resolution')
    return deps, package.get('name')


def _go_require_entry(line, single=False):
    parts = line.split()
    if len(parts) < (3 if single else 2):
        raise ValueError('invalid go.mod require entry')
    return parts[1] if single else parts[0]


def _go_directive(line, deps):
    if line.startswith('module '):
        return line.split(None, 1)[1], False
    if line == 'require (':
        return None, True
    if line.startswith('require '):
        deps.add(_go_require_entry(line, single=True))
        return None, False
    if line.startswith(('go ', 'toolchain ', 'exclude ',
                        'retract ', 'godebug ')):
        return None, False
    raise ValueError('unsupported go.mod directive: ' + line)


def _go_manifest(source):
    module, deps, require = None, set(), False
    for raw in source.splitlines():
        line = raw.split('//', 1)[0].strip()
        if not line:
            continue
        if line == ')' and require:
            require = False
            continue
        if require:
            deps.add(_go_require_entry(line))
        else:
            declared, require = _go_directive(line, deps)
            module = declared or module
    if not module or require:
        raise ValueError('go.mod module or require block is incomplete')
    return deps, module


def _manifest(target, source):
    if source is None:
        raise ValueError('required dependency manifest is missing')
    if _ext(target) in JS:
        return _json_manifest(source)
    if _ext(target) == '.rs':
        return _cargo_manifest(source)
    return _go_manifest(source)


def _js_imports(root, source):
    names, unsupported = set(), []
    for node in _walk(root):
        if node.type in ('import_statement', 'export_statement'):
            value = node.child_by_field_name('source')
            if value is None:
                continue
            literal = _text(value, source)
            if len(literal) < 2 or literal[0] not in ('"', "'") or literal[-1] != literal[0]:
                unsupported.append('nonliteral import/export')
                continue
            name = literal[1:-1]
            if name.startswith(('.', '/', 'node:')):
                continue
            parts = name.split('/')
            names.add('/'.join(parts[:2]) if name.startswith('@') else parts[0])
        elif node.type == 'call_expression':
            function = node.child_by_field_name('function')
            if function and _text(function, source) in ('require', 'import'):
                unsupported.append('dynamic import or require')
    return names, unsupported


def _go_imports(root, source):
    names = set()
    for node in _walk(root):
        if node.type == 'import_spec':
            value = node.child_by_field_name('path')
            if value is None:
                raise ValueError('Go import lacks path')
            names.add(_text(value, source).strip('"' + chr(96)))
    return names, []


def _rust_imports(root, source):
    names, unsupported = set(), []
    for node in _walk(root):
        if node.type == 'use_declaration':
            value = node.child_by_field_name('argument')
            if value:
                match = re.match(r'(?:::)?([A-Za-z_][A-Za-z_0-9]*)',
                                 _text(value, source))
                if match:
                    names.add(match.group(1))
                else:
                    unsupported.append('Rust use tree root cannot be resolved')
        elif node.type == 'extern_crate_declaration':
            value = node.child_by_field_name('name')
            if value:
                names.add(_text(value, source))
    return names - RUST_LOCAL, unsupported


def _imports(target, root, source):
    if _ext(target) in JS:
        return _js_imports(root, source)
    if _ext(target) == '.go':
        return _go_imports(root, source)
    return _rust_imports(root, source)


def _external(target, name, module):
    if _ext(target) == '.go':
        return not (name == module or name.startswith((module or '') + '/')) and '.' in name.split('/')[0]
    return name != module


def _declared(target, name, deps):
    if _ext(target) == '.go':
        return any(name == dep or name.startswith(dep + '/') for dep in deps)
    return name in deps


def _parameters(node):
    params = node.child_by_field_name('parameters')
    if params is None:
        return 0
    if params.type == 'identifier':
        return 1
    count = 0
    for child in params.named_children:
        if child.type in ('required_parameter', 'optional_parameter', 'parameter',
                          'variadic_parameter_declaration', 'self_parameter', 'identifier',
                          'assignment_pattern', 'rest_pattern', 'object_pattern',
                          'array_pattern'):
            count += 1
        elif child.type == 'parameter_declaration':
            count += max(1, sum(item.type == 'identifier' for item in child.named_children))
    return count


def _metrics(function, source):
    complexity, nesting, opaque = 1, 0, False
    def visit(node, depth):
        nonlocal complexity, nesting, opaque
        for child in node.named_children:
            if child.type in FUNCTIONS:
                continue
            complexity += int(child.type in BRANCHES)
            if child.type == 'binary_expression':
