_OBJECT_CACHE = ContextVar('kdd_git_objects', default=None)


@contextmanager
def object_cache():
    if _OBJECT_CACHE.get() is not None:
        yield
        return
    token = _OBJECT_CACHE.set({})
    try:
        yield
    finally:
        _OBJECT_CACHE.reset(token)


def _key(root, kind, revision, *parts):
