                if not source.is_file():raise ValueError('Missing source file')
                args+=['--file',source.relative_to(self.root).as_posix()]
        allowed={'SYSTEMROOT','WINDIR','PATH','PATHEXT','TEMP','TMP','USERPROFILE','HOMEDRIVE','HOMEPATH','LOCALAPPDATA','APPDATA','PROGRAMFILES','PROGRAMFILES(X86)','PROGRAMDATA','COMSPEC','LANG','LC_ALL','NUMBER_OF_PROCESSORS','PROCESSOR_ARCHITECTURE','GIT_CONFIG_GLOBAL','GIT_OPTIONAL_LOCKS'}
        env={k:v for k,v in environment(self.root).items() if k.upper() in allowed}
        env.update(ENTIRE_REPO_ROOT=str(self.root),ENTIRE_PLUGIN_DATA_DIR=str(cache),ENTIRE_CLI_VERSION='0.12.2')
        started=time.perf_counter()
        try:
            r=contained_run(args,cwd=str(self.root),timeout=60,env=env,capture_output=True,text=True,encoding='utf-8',errors='replace',creationflags=subprocess.BELOW_NORMAL_PRIORITY_CLASS)
            response={'exit_code':r.returncode,'stdout':r.stdout,'stderr':r.stderr}
        except subprocess.TimeoutExpired:
            response={'exit_code':124,'stdout':'','stderr':'Graph operation exceeded 60 seconds'}
        entry={**request,'seconds':time.perf_counter()-started,'exit_code':response['exit_code'],
               'output_bytes':len(response['stdout'].encode()),'output_sha256':sha(response['stdout'].encode())}
        self.calls.append(entry)
        with (self.record/'graph-calls.jsonl').open('a',encoding='utf-8') as stream:stream.write(json.dumps(entry)+'\n')
        dump(self.record/'graph-responses'/(request['id']+'.json'),response)
        return response
    def work(self):
        while not self.stop.wait(.05):
            queue=self.within(self.root/'.benchmark-cache/requests')
            for path in sorted(queue.glob('*.json')):
                if path.name in self.seen:continue
                self.seen.add(path.name)
                if not re.fullmatch(r'[0-9a-f]{32}\.json',path.name):continue
                try:
                    path=self.within(path)
                    if path.stat().st_size>16384:raise ValueError('Request too large')
                    request=json.loads(path.read_text(encoding='utf-8'))
                    if request.get('id')!=path.stem:raise ValueError('Request identity mismatch')
                    response=self.execute(request)
                except Exception as exc:response={'exit_code':1,'stdout':'','stderr':str(exc)}
                target=self.within(self.root/'.benchmark-cache/responses'/path.name)
                target.parent.mkdir(parents=True,exist_ok=True)
                temporary=target.with_suffix('.tmp');dump(temporary,response);temporary.replace(target)


def goal(case,arm):
    common=(case['goal']+'\n\n'
        'Este es un benchmark de regresiones sembradas en una copia, no una incidencia pendiente del repositorio activo. '
        'No se proporcionan nombres de archivos objetivo, simbolos ni tests concretos: descubrelos con las herramientas. '
        'Consulta las reglas KDD, los contratos que descubras y sus pruebas selladas. Puedes modificar codigo Python de produccion '
        'bajo scripts/ y src/ y anadir modulos de produccion; tests, contratos, specs, guias, fixtures y herramientas del benchmark estan congelados. '
        'No alteres oraculos ni sellos. Ejecuta las pruebas focalizadas pertinentes y validacion de contratos; evita la suite global completa. '
        'El contexto KDD fue ensamblado por el padre y sus guardrails pasaron, sin inyectar rutas objetivo en el enunciado. '
        'Entorno Windows controlado: TEMP y TMP apuntan a .benchmark-tmp dentro de la copia; Git tiene autocrlf=input, safecrlf=false y cr-at-eol. '
        'No normalices masivamente finales de linea, no busques conversores y no cambies configuracion Git: CRLF no es un fallo funcional; '
        'usa git diff --check para comprobarlo. No hagas commits en esta copia, red, otros agentes, acceso a otros repositorios o configuraciones de usuario; '
        'los tests pueden crear sus propios repositorios temporales. No uses Entire core ni otras sesiones. '
        'Presupuesto: 900 segundos para diagnosticar, implementar y comprobar. Informa cambios, descubrimiento, pruebas y limitaciones; no afirmes certificacion integral KDD.\n\n')
    if arm=='graph':
        return common+('Dispones de Graph mediante python .benchmark-tools/graph_tool.py. Ejecuta al menos una query exitosa antes de editar; '
            'usa --query con una descripcion del problema. Puedes hacer mas consultas y usar impact, neighbors o def con --symbol y --file opcional, '
            'o query --callee-hop, segun lo que descubras. Las consultas leen el commit inicial de esta copia; tras editar contrasta con lectura local. '
            'El adaptador es de solo lectura y su coste esta incluido. El consejo de ejecutar pruebas es el mismo en ambas variantes.')
    return common+'Trabaja con busqueda y lectura locales habituales. No ejecutes Graph, Entire ni .benchmark-tools/graph_tool.py.'


