def freeze_check(plan):
    assert sha((BASE/'plan.json').read_bytes())==(BASE/'plan.sha256').read_text().strip()
    for name,digest in plan['frozen_files'].items():assert sha((BASE/name).read_bytes())==digest,name
    for name,digest in plan['binaries'].items():assert sha(Path(name).read_bytes())==digest,name


class Observer:
    """Record approximate arrival times of raw CLI events without altering them."""
    def __init__(self,path,started):
        self.path=path;self.started=started;self.stop=threading.Event();self.items=[]
        self.thread=threading.Thread(target=self.work,daemon=True)
    def __enter__(self):self.thread.start();return self
    def __exit__(self,*args):self.stop.set();self.thread.join(timeout=3);self.read()
    def read(self):
        if not self.path.exists():return
        lines=self.path.read_text(encoding='utf-8',errors='replace').splitlines()
        for line in lines[len(self.items):]:
            try:event=json.loads(line)
            except json.JSONDecodeError:break
            self.items.append({'seconds':time.perf_counter()-self.started,'event':event})
    def work(self):
        while not self.stop.wait(.1):self.read()


def diagnostic(case,prepared,observed):
    anchors=prepared['repair_anchors'];seen=set();first=None;before_edit=True;commands=0;bytes_seen=0
    definitions=set();first_edit_seconds=None;format_commands=0;temporary_errors=0;queries_before_edit=0
    for record in observed:
        event=record['event'];item=event.get('item',{})
        if event.get('type')=='item.completed' and item.get('type')=='file_change' and item.get('status')=='completed':
            before_edit=False
            if first_edit_seconds is None:first_edit_seconds=record['seconds']
        if event.get('type')!='item.completed' or item.get('type')!='command_execution':continue
        cmd=item.get('command','');output=item.get('aggregated_output','')
        if re.search(r'(?i)dos2unix|unix2dos|CRCRLF|CRLF|ReadAllBytes|Replace\(.*`r',cmd):format_commands+=1
        if re.search(r'(?i)PermissionError.*(?:tmp|temp)|Access.*denied.*(?:tmp|temp)',output):temporary_errors+=1
        if before_edit and 'graph_tool.py query' in cmd and item.get('exit_code')==0:queries_before_edit+=1
        if not before_edit or not re.search(r'Get-Content|Select-String|\brg\b|graph_tool\.py|\bcat\b|\btype\b',cmd):continue
        commands+=1;bytes_seen+=len(output.encode('utf-8'))
        normalized=[]
        for line in output.splitlines():
            line=re.sub(r'^.*?\.py:\d+[:-]\s*','',line)
            line=re.sub(r'^\s*\d+[:-]\s*','',line)
            normalized.append(line.strip())
        text='\n'.join(normalized)
        definitions.update(re.findall(r'^\s*(?:async\s+)?def\s+(\w+)\s*\(',text,re.M))
        for name,anchor in anchors.items():
            if '\n'.join(anchor) in text:
                seen.add(name)
                if first is None:first=record['seconds']
    return {'repair_anchor_coverage':len(seen)/len(anchors),'expected_anchors':list(anchors),'observed_anchors':sorted(seen),
        'first_repair_anchor_seconds':first,'first_recorded_edit_seconds':first_edit_seconds,'pre_edit_read_search_commands':commands,
        'pre_edit_output_bytes':bytes_seen,'definition_names_seen':sorted(definitions),'newline_tool_commands':format_commands,
        'temporary_permission_error_outputs':temporary_errors,'successful_queries_before_first_recorded_edit':queries_before_edit,
        'limits':'Approximate CLI event arrival times at 100ms polling; anchors are an observable coverage proxy. Shell edits without file_change events can make the boundary incomplete.'}


def run():
    import ctypes
    ctypes.windll.kernel32.SetPriorityClass(ctypes.windll.kernel32.GetCurrentProcess(),0x00004000)
    plan=json.loads((BASE/'plan.json').read_text(encoding='utf-8'));freeze_check(plan)
