    for index,item in enumerate(plan['order']):
        freeze_check(plan);case=next(c for c in CASES if c['id']==item['task']);root=BASE/'runs'/item['id']
        assert tracked_hashes(root)==plan['prepared'][case['id']]['hashes']
        record=BASE/'records'/item['id'];record.mkdir(parents=True)
        task_goal=goal(case,item['arm']);(record/'goal.txt').write_text(task_goal,encoding='utf-8',newline='\n')
        # Enunciado is audited against hidden implementation and oracle paths.
        assert not any(p in task_goal for p in case['gold_files']+case['contracts']+[m.replace('.','/')+'.py' for m in case['tests']])
        args=[sys.executable,str(WRAPPER),'--role','dev','--model',plan['model'],'--cwd',str(root),'--sandbox','workspace-write',
              '--timeout',str(plan['timeout_seconds']),'--output',str(record/'final.txt'),'--config','model_reasoning_effort="medium"',
              '--kdd-root',str(root),'--kdd-prefix','.agents/AGENTS.md','--kdd-prefix','knowledge/OKF-SPEC.md','--goal',task_goal]
        print(json.dumps({'event':'starting','run':item['id'],'position':index+1,'total':len(plan['order'])}),flush=True)
        started=time.perf_counter();timed_out=False
        with GraphBridge(root,record) as bridge,Observer(record/'events.jsonl',started) as observer,(record/'events.jsonl').open('w',encoding='utf-8') as out,(record/'stderr.txt').open('w',encoding='utf-8') as err:
            try:
                r=contained_run(args,cwd=str(root),env=environment(root,True),timeout=plan['timeout_seconds']+20,stdin=subprocess.DEVNULL,
                    stdout=out,stderr=err,text=True,encoding='utf-8',creationflags=subprocess.BELOW_NORMAL_PRIORITY_CLASS)
                exit_code=r.returncode;timed_out=exit_code==124
            except subprocess.TimeoutExpired:exit_code=124;timed_out=True
        agent_seconds=time.perf_counter()-started
        dump(record/'observed-events.json',observer.items)
        events=[r['event'] for r in observer.items]
        completions=[e for e in events if e.get('type')=='turn.completed'];usage=completions[0].get('usage') if len(completions)==1 else None
        thread=next((e.get('thread_id') for e in events if e.get('type')=='thread.started'),None)
        commands=[e['item'] for e in events if e.get('type')=='item.completed' and e.get('item',{}).get('type')=='command_execution']
        original=plan['prepared'][case['id']]['hashes'];current=tracked_hashes(root)
        changed=sorted(p for p in set(original)|set(current) if original.get(p)!=current.get(p))
        untracked=[p for p in git('ls-files','--others','--exclude-standard','-z',cwd=root).split('\0') if p]
        perimeter_ok=all(production(p) for p in changed+untracked)
        context_diagnostic=diagnostic(case,plan['prepared'][case['id']],observer.items)
        calls=bridge.calls
        treatment_ok=(any(c['mode']=='query' and c['exit_code']==0 for c in calls) and context_diagnostic['successful_queries_before_first_recorded_edit']>0) if item['arm']=='graph' else (not calls and not any(re.search(r'graph_tool\.py|entire[ -]graph',c.get('command',''),re.I) for c in commands))
        start_verify=time.perf_counter()
