        diff=command([GIT,'diff','--check'],cwd=root,check=False)
        verified['diff_check']={'exit_code':diff.returncode,'stdout':diff.stdout,'stderr':diff.stderr}
        verification_seconds=time.perf_counter()-start_verify
        success=exit_code==0 and not timed_out and usage is not None and perimeter_ok and treatment_ok and bool(changed or untracked) and all(v['exit_code']==0 for v in verified.values())
        result={**item,'model':plan['model'],'session_id':thread,'exit_code':exit_code,'timed_out':timed_out,'success':success,
            'agent_seconds':agent_seconds,'verification_seconds':verification_seconds,'total_seconds':agent_seconds+verification_seconds,
            'usage':usage,'changed_files':changed,'untracked_files':untracked,'perimeter_ok':perimeter_ok,'treatment_ok':treatment_ok,
            'verification':verified,'graph_calls':calls,'command_count':len(commands),'context_diagnostic':context_diagnostic}
        if usage:
            result.update(input_tokens=usage['input_tokens'],cached_input_tokens=usage.get('cached_input_tokens',0),
                fresh_input_tokens=usage['input_tokens']-usage.get('cached_input_tokens',0),output_tokens=usage['output_tokens'],
                total_tokens=usage['input_tokens']+usage['output_tokens'])
        dump(record/'result.json',result)
        (record/'candidate.patch').write_text(git('diff','--no-ext-diff',cwd=root),encoding='utf-8',newline='\n')
        for p in untracked:
            dest=record/'new-production-files'/p;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(root/p,dest)
        with results_path.open('a',encoding='utf-8') as stream:stream.write(json.dumps(result,ensure_ascii=False)+'\n')
        print(json.dumps({'event':'finished','run':item['id'],'success':success,'seconds':round(agent_seconds,2),'usage':usage,
            'commands':len(commands),'graph_calls':len(calls),'perimeter_ok':perimeter_ok,'treatment_ok':treatment_ok,
            'checks':{k:v['exit_code'] for k,v in verified.items()},'context_coverage':context_diagnostic['repair_anchor_coverage'],
            'newline_commands':context_diagnostic['newline_tool_commands']},ensure_ascii=True),flush=True)
        if index==0 and usage is None:raise RuntimeError('First measured attempt has no usage; stop on systemic failure')
    freeze_check(plan);print(json.dumps({'event':'all_complete','runs':len(plan['order'])}),flush=True)


