"""Read native Entire state. No candidate imports, expected values, or mutations."""
from __future__ import annotations
import hashlib
import json
import os
from pathlib import Path
import subprocess
import time

ROOT = Path(__file__).resolve().parent.parent
REPOSITORY = "et/kdd-entire-lab-c7f091/candidate"
REPO_ID = "01M61V4BZZC18115NB7839WSGH"
REMOTE = "entire://aws-us-east-2.entire.io/" + REPOSITORY
ENTIRE = r"C:\Users\Administrador\.local\bin\entire.exe"
GIT = r"C:\Program Files\Git\cmd\git.exe"
ISOLATION_ID = "kdd-entire-20261028-c7f091"


def digest(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def read(path):
    return json.loads(Path(path).read_text(encoding="utf-8-sig"))


def command(argv, allowed=(0,), timeout=45):
    """Only fixed read operations reach this function, without shell expansion."""
    env = dict(os.environ, GIT_OPTIONAL_LOCKS="0", GIT_TERMINAL_PROMPT="0",
               PYTHONNOUSERSITE="1")
    for key in ("ENTIRE_TOKEN", "ENTIRE_API_BASE_URL", "ENTIRE_CONTEXT",
                "GIT_DIR", "GIT_WORK_TREE", "GIT_CONFIG_COUNT"):
        env.pop(key, None)
    start = time.monotonic()
    completed = subprocess.run(argv, cwd=ROOT / "trusted", env=env,
        stdin=subprocess.DEVNULL, capture_output=True, text=True,
        encoding="utf-8", errors="strict", timeout=timeout, shell=False)
    if completed.returncode not in allowed:
        raise RuntimeError("read operation failed")
    if len(completed.stdout) > 4_000_000:
        raise RuntimeError("response exceeds capture limit")
    return {"argv": argv, "returncode": completed.returncode,
            "stdout": completed.stdout, "stderr": completed.stderr,
            "elapsed_ms": round((time.monotonic() - start) * 1000)}


def api(suffix):
    allowed = {"/trails/gates", "/trails/gate-settings", "/trails/1/mergeability"}
    if suffix not in allowed:
        raise ValueError("unapproved read endpoint")
    result = command([ENTIRE, "api", "--context", "us.auth.entire.io", "--to", "cell",
                      "/api/v1/repos/" + REPO_ID + suffix])
    return json.loads(result["stdout"])


def head(branch):
    if branch not in ("main", "codex/lab-smoke", "codex/direct-push-probe"):
        raise ValueError("branch outside lab allowlist")
    result = command([GIT, "ls-remote", REMOTE, "refs/heads/" + branch])
    lines = result["stdout"].splitlines()
    if len(lines) != 1:
        raise ValueError("expected exactly one branch")
    sha, ref = lines[0].split()
    if ref != "refs/heads/" + branch or len(sha) != 40:
        raise ValueError("unexpected branch response")
    return sha


def findings():
    result = command([ENTIRE, "trail", "finding", "list", "candidate/1",
        "--context", "us.auth.entire.io", "--project", "et/kdd-entire-lab-c7f091",
        "--repo", REPOSITORY, "--status", "any", "--freshness", "any", "--json"])
    data = json.loads(result["stdout"])
    if data.get("has_more"):
        raise ValueError("findings response is incomplete")
    return data


def capture(case_id, data):
    """Hash actual persisted bytes; every artifact URI resolves in this lab."""
    directory = ROOT / "evidence" / "observations" / case_id
    directory.mkdir(parents=True, exist_ok=True)
    content = (json.dumps(data, ensure_ascii=True, sort_keys=True, indent=2) + "\n").encode()
    fingerprint = hashlib.sha256(content).hexdigest()
    path = directory / (fingerprint + ".json")
    if not path.exists():
        with path.open("xb") as stream:
            stream.write(content)
    elif path.read_bytes() != content:
        raise ValueError("artifact collision")
    relative = path.relative_to(ROOT / "evidence").as_posix()
    return {"uri": "artifact://" + ISOLATION_ID + "/" + relative, "sha256": fingerprint}


def observe(case, context):
    # No access to case['expected']; observation comes from independent API reads.
    case_id = case["id"]
    if context["repository"] != REPOSITORY or context["isolation_id"] != ISOLATION_ID:
        raise ValueError("observer bound to another lab")
    if case_id not in {"FIND-01", "FIND-05", "TRAIL-04"}:
        return {"execution": "not_run", "reason": "real adapter or dependency unavailable"}
    preparation = read(ROOT / "config" / "prepared.json")
    if case_id not in preparation["cases"]:
        return {"execution": "not_run", "reason": "real action not prepared"}
    receipt = read(ROOT / preparation["cases"][case_id])
    current = head("codex/lab-smoke")
    mergeability = api("/trails/1/mergeability")
    if mergeability["head_sha"] != current:
        raise ValueError("remote head and gate revision disagree")
    snapshot = {"case_id": case_id, "repository": REPOSITORY,
        "isolation_id": ISOLATION_ID, "time_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "action_receipt": receipt, "mergeability": mergeability,
        "policy": api("/trails/gates"), "settings": api("/trails/gate-settings")}
    if case_id.startswith("FIND-"):
        listing = findings()
        snapshot["findings"] = listing
        high = next(f for f in listing["findings"] if f["id"] == receipt["finding_id"])
        if high["repositoryId"] != REPO_ID or high["trailId"] != preparation["change_id"]:
            raise ValueError("finding belongs to another change")
        if case_id == "FIND-01":
            gate = next(g for g in mergeability["gates"] if g["gate_key"] == "findings")
            if gate["head_sha"] != current or gate["state"] != "evaluated":
                raise ValueError("findings gate is not current")
            if not gate["blocking"] or not receipt["dry_run_attempted"]:
                raise ValueError("required native gate/action is missing")
            values = {"integration_allowed": mergeability["mergeable"],
                "blocking_finding_open": high["status"] == "open" and
                    high["staleOutcome"] == "current" and high["severity"] == "high" and
                    gate["status"] == "failed" and gate["value"]["agent_blocking_findings"] > 0}
        else:
            second = next(f for f in listing["findings"] if f["id"] == receipt["second_finding_id"])
            if second["reviewId"] == high["reviewId"] or second["createdAt"] <= high["createdAt"]:
                raise ValueError("second real review was not created")
            values = {"prior_finding_resolved_by_omission": high["status"] == "resolved"}
    else:
        before = receipt["before_main"]
        after = head("main")
        snapshot["main_after"] = after
        snapshot["protection"] = json.loads(command([ENTIRE, "repo", "protection", "list",
            REPOSITORY, "--context", "us.auth.entire.io", "--json"])["stdout"])
        result = receipt["push"]
        # A real denied push must identify the server rule, not network/auth failure.
        denial = (result["returncode"] != 0 and
                  "server-side" in result["stderr"].lower())
        if not denial and result["returncode"] != 0:
            raise ValueError("push failed without a confirmed server protection denial")
        if not any(rule["ref"] == "refs/heads/main" and rule["serverSideMergeOnly"]
                   for rule in snapshot["protection"]):
            raise ValueError("protection is not configured")
        values = {"direct_push_allowed": result["returncode"] == 0,
                  "head_unchanged": after == before}
    artifact = capture(case_id, snapshot)
    return {"case_id": case_id, "execution": "completed", "performed": True,
        "repository": REPOSITORY, "isolation_id": ISOLATION_ID,
        "head_sha": current, "evidence": [artifact], "observed": values}

