"""Synthetic negative controls for the observer, never live scenario results."""
import importlib.util
import json
from pathlib import Path
import tempfile
import unittest
from unittest.mock import patch

spec = importlib.util.spec_from_file_location("lab_observer_tests_target", Path(__file__).with_name("observer.py"))
o = importlib.util.module_from_spec(spec)
spec.loader.exec_module(o)
SHA = "a" * 40
CONTEXT = {"repository": o.REPOSITORY, "isolation_id": o.ISOLATION_ID}


class ObserverTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        self.root_patch = patch.object(o, "ROOT", self.root)
        self.root_patch.start()
        (self.root / "config").mkdir()
        (self.root / "evidence/actions").mkdir(parents=True)
        cases = {c: "evidence/actions/" + c + ".json" for c in ("FIND-01", "FIND-05", "TRAIL-04")}
        self.write("config/prepared.json", {"change_id": "change-id", "cases": cases})
        for name in cases.values():
            self.write(name, {"finding_id": "high", "second_finding_id": "low", "dry_run_attempted": True,
                "before_main": SHA, "push": {"returncode": 1,
                "stderr": "[remote rejected] main (protected branch accepts server-side merges only)"}})
        self.merge = {"head_sha": SHA, "mergeable": False, "gates": [{
            "gate_key": "findings", "head_sha": SHA, "state": "evaluated", "blocking": True,
            "status": "failed", "value": {"agent_blocking_findings": 1}}]}
        self.high = {"id": "high", "repositoryId": o.REPO_ID, "trailId": "change-id",
            "status": "open", "staleOutcome": "current", "severity": "high", "reviewId": "r1", "createdAt": "2026-01-01"}
        self.low = {**self.high, "id": "low", "severity": "low", "reviewId": "r2", "createdAt": "2026-01-02"}
        self.patches = [patch.object(o, "head", return_value=SHA),
            patch.object(o, "api", side_effect=lambda path: self.merge if path.endswith("mergeability") else {}),
            patch.object(o, "findings", return_value={"findings": [self.high, self.low]}),
            patch.object(o, "command", return_value={"stdout": json.dumps([{
                "ref": "refs/heads/main", "serverSideMergeOnly": True}])})]
        for item in self.patches:
            item.start()

    def tearDown(self):
        for item in reversed(self.patches):
            item.stop()
        self.root_patch.stop()
        self.temp.cleanup()

    def write(self, name, value):
        (self.root / name).write_text(json.dumps(value), encoding="utf-8")

    def observe(self, name):
        return o.observe({"id": name, "expected": {"fabricated": True}}, CONTEXT)

    def test_real_properties_do_not_copy_expected(self):
        value = self.observe("FIND-01")["observed"]
        self.assertEqual(value, {"integration_allowed": False, "blocking_finding_open": True})
        self.assertNotIn("fabricated", value)

    def test_wrong_lab_refused(self):
        with self.assertRaises(ValueError):
            o.observe({"id": "FIND-01"}, {**CONTEXT, "repository": "et/production/main"})

    def test_revision_mismatch_not_pass(self):
        self.merge["head_sha"] = "b" * 40
        with self.assertRaises(ValueError):
            self.observe("FIND-01")

    def test_stale_gate_not_pass(self):
        self.merge["gates"][0]["head_sha"] = "b" * 40
        with self.assertRaises(ValueError):
            self.observe("FIND-01")

    def test_finding_other_repository_not_pass(self):
        self.high["repositoryId"] = "other"
        with self.assertRaises(ValueError):
            self.observe("FIND-01")

    def test_resolved_high_is_observed_as_failure(self):
        self.high["status"] = "resolved"
        self.assertFalse(self.observe("FIND-01")["observed"]["blocking_finding_open"])

    def test_same_review_cannot_prove_omission(self):
        self.low["reviewId"] = "r1"
        with self.assertRaises(ValueError):
            self.observe("FIND-05")

    def test_old_finding_resolution_is_not_hidden(self):
        self.high["status"] = "resolved"
        self.assertTrue(self.observe("FIND-05")["observed"]["prior_finding_resolved_by_omission"])

    def test_auth_failure_not_server_protection(self):
        receipt = json.loads((self.root / "evidence/actions/TRAIL-04.json").read_text())
        receipt["push"]["stderr"] = "authentication failed"
        self.write("evidence/actions/TRAIL-04.json", receipt)
        with self.assertRaises(ValueError):
            self.observe("TRAIL-04")

    def test_allowed_push_is_reported_not_masked(self):
        receipt = json.loads((self.root / "evidence/actions/TRAIL-04.json").read_text())
        receipt["push"] = {"returncode": 0, "stderr": ""}
        self.write("evidence/actions/TRAIL-04.json", receipt)
        self.assertTrue(self.observe("TRAIL-04")["observed"]["direct_push_allowed"])

    def test_unimplemented_case_never_passes(self):
        self.assertEqual(self.observe("OK-01")["execution"], "not_run")

    def test_evidence_hash_resolves_to_exact_file_bytes(self):
        result = self.observe("FIND-01")
        item = result["evidence"][0]
        relative = item["uri"].split(o.ISOLATION_ID + "/")[1]
        self.assertEqual(o.digest(self.root / "evidence" / relative), item["sha256"])

    def test_receipt_path_cannot_escape_action_root(self):
        self.write("config/prepared.json", {"cases": {"FIND-01": "config/prepared.json"}})
        with self.assertRaises(ValueError):
            self.observe("FIND-01")


if __name__ == "__main__":
    unittest.main()

