"""Synthetic checks for interpreting CLI responses; no network or real merges."""
import copy
import importlib.util
import json
from pathlib import Path
import unittest

spec = importlib.util.spec_from_file_location("observer_access_test_target", Path(__file__).with_name("observe_configuration.py"))
observer = importlib.util.module_from_spec(spec)
spec.loader.exec_module(observer)
HEAD = "a" * 40


class TrailsAccessTests(unittest.TestCase):
    def setUp(self):
        self.shown = {"id": "01M62DW2N4M89QJSWGPMEG986W", "number": 3, "changes": [{
            "id": "01M62E0N83TCSTVZ7P8BJTC2G8", "repositoryId": observer.REPO_ID,
            "branch": "codex/lab-ci-validation"}]}
        self.merged = {"headSha": HEAD, "change": "kdd-entire-lab-c7f091/1", "dryRun": True,
            "merged": False, "bypassed": False, "wouldBypass": False, "mergeable": False,
            "blockers": [{"gateKey": "checks", "status": "pending"}]}

    def validate(self, shown=None, merged=None):
        return observer.validate_trail_access({"returncode": 0, "stdout": json.dumps(shown or self.shown)},
            {"returncode": 1, "stdout": json.dumps(merged or self.merged)}, HEAD)

    def test_commands_avoid_lowercasing_project_route_and_never_merge(self):
        show, merge = observer.trail_read_commands()
        self.assertNotIn("--project", show + merge)
        self.assertIn("--dry-run", merge)
        self.assertNotIn("--force", merge)
        self.assertEqual(show[3], "kdd-entire-lab-c7f091/1")

    def test_pending_gate_exit_one_confirms_access(self):
        self.assertTrue(self.validate()["merge_check_access"])
        self.assertFalse(self.validate()["merge_performed"])

    def test_http_error_exit_one_does_not_confirm_access(self):
        with self.assertRaises(ValueError):
            observer.validate_trail_access({"returncode": 0, "stdout": json.dumps(self.shown)},
                {"returncode": 1, "stdout": '{"error":"no read access to repo"}'}, HEAD)

    def test_wrong_repository_is_rejected(self):
        shown = copy.deepcopy(self.shown)
        shown["changes"][0]["repositoryId"] = "another-repository"
        with self.assertRaises(ValueError):
            self.validate(shown=shown)

    def test_stale_revision_is_rejected(self):
        with self.assertRaises(ValueError):
            self.validate(merged={**self.merged, "headSha": "b" * 40})

    def test_real_or_bypassed_merge_is_rejected(self):
        for field, value in (("dryRun", False), ("merged", True), ("bypassed", True), ("wouldBypass", True)):
            with self.subTest(field=field), self.assertRaises(ValueError):
                self.validate(merged={**self.merged, field: value})

    def test_nongate_failure_cannot_look_like_a_pending_check(self):
        with self.assertRaises(ValueError):
            self.validate(merged={**self.merged, "blockers": [{"gateKey": "up_to_date", "status": "failed"}]})

    def test_empty_workflow_list_is_not_paused_configuration(self):
        self.assertFalse(observer.validate_paused_workflows({"workflows": []}))

    def test_enabled_or_missing_workflow_is_not_paused(self):
        entries = [{"path": p, "state": "disabled_manually"} for p in
                   (".github/workflows/lab.yml", ".github/workflows/fixtures.yml")]
        self.assertTrue(observer.validate_paused_workflows({"workflows": entries}))
        self.assertFalse(observer.validate_paused_workflows({"workflows": entries[:1]}))
        entries[0]["state"] = "active"
        self.assertFalse(observer.validate_paused_workflows({"workflows": entries}))


